                .andExpect(status().isForbidden())
                .andExpect(jsonPath("$.code").value("ERASER_ROLE_REQUIRED"));
        progress(null, "subj-e", "RESEARCH", 1)
                .andExpect(status().isForbidden())
                .andExpect(jsonPath("$.code").value("ERASER_ROLE_REQUIRED"));
        progress("VIEWER", "subj-e", "RESEARCH", 1)
                .andExpect(status().isForbidden());
